macro_rules! vec_example {
    // Пустой вектор
    () => { Vec::new() };

    // Один элемент
    ($elem:expr) => { {
        let mut v = Vec::new();
        v.push($elem);
        v
    }};

    // Несколько элементов
    ($($elem:expr),+) => { {
        let mut v = Vec::new();
        $(v.push($elem);)+
        v
    }};
}

fn main() {
    let v1 = vec_example![];
    let v2 = vec_example![1];
    let v3 = vec_example![1, 2, 3, 4];
}

macro_rules! print_all {
    ($($arg:expr),*) => {
        $(println!("{}", $arg);)*
    };
}

macro_rules! sum {
    ($($x:expr),+) => {
        0 $(+ $x)*
    };
}

fn main() {
    print_all!("a", "b", "c");
    println!("Sum: {}", sum!(1, 2, 3, 4)); // 10
}

macro_rules! demo {
    // item — элемент (fn, struct, mod...)
    ($item:item) => { $item };

    // block — блок { ... }
    ($block:block) => { $block };

    // stmt — statement (let x = 1;)
    ($stmt:stmt) => { $stmt };

    // expr — выражение
    ($expr:expr) => { $expr };

    // ty — тип
    ($ty:ty) => { std::any::type_name::<$ty>() };

    // ident — идентификатор
    ($ident:ident) => { stringify!($ident) };

    // path — путь (std::vec::Vec)
    ($path:path) => { $path };

    // meta — атрибут #[...]
    ($meta:meta) => { $meta };

    // tt — token tree (один токен или группа)
    ($tt:tt) => { $tt };

    // vis — visibility (pub, pub(crate))
    ($vis:vis) => { $vis };

    // lifetime — 'a
    ($lt:lifetime) => { $lt };
}

macro_rules! html {
    ($($tag:ident { $($content:tt)* } )*) => {
        {
            let mut output = String::new();
            $(
                output.push_str(&format!("<{}>", stringify!($tag)));
                html_inner!(@content $($content)*; output);
                output.push_str(&format!("</{}>", stringify!($tag)));
            )*
            output
        }
    };
}

macro_rules! html_inner {
    (@content $text:expr; $out:expr) => {
        $out.push_str(&$text);
    };
    (@content $tag:ident { $($content:tt)* }; $out:expr) => {
        $out.push_str(&format!("<{}>", stringify!($tag)));
        html_inner!(@content $($content)*; $out);
        $out.push_str(&format!("</{}>", stringify!($tag)));
    };
}

fn main() {
    let page = html! {
        html {
            body {
                h1 { "Hello" }
                p { "World" }
            }
        }
    };
    println!("{}", page);
}

